1	import { Router } from "express";
2	import type { Db } from "@paperclipai/db";
3	import {
4	  issueGraphLivenessAutoRecoveryRequestSchema,
5	  patchInstanceExperimentalSettingsSchema,
6	  patchInstanceGeneralSettingsSchema,
7	} from "@paperclipai/shared";
8	import { assertBoardOrgAccess, assertInstanceAdmin } from "./authz.js";
9	import { heartbeatService, instanceSettingsService, logActivity } from "../services/index.js";
10	import { expressHandler } from "../http/express-adapter.js";
11	import type { Handler } from "../http/types.js";
12	import type { StorageService } from "../storage/types.js";
13	
14	function buildHandlers(db: Db) {
15	  const svc = instanceSettingsService(db);
16	  const heartbeat = heartbeatService(db);
17	
18	  // server/src/routes/instance-settings.ts:28
19	  const getGeneralSettings: Handler = async (ctx) => {
20	    assertBoardOrgAccess(ctx);
21	    return Response.json(await svc.getGeneral());
22	  };
23	
24	  // server/src/routes/instance-settings.ts:35
25	  const patchGeneralSettings: Handler = async (ctx) => {
26	    assertInstanceAdmin(ctx);
27	    const body = await ctx.json();
28	    const patch = patchInstanceGeneralSettingsSchema.parse(body);
29	    const updated = await svc.updateGeneral(patch);
30	
31	    // ctx.actor lacks `runId`; log with null runId.
32	    // TODO(cloudflare): thread runId through ActorContext.
33	    const actorType = ctx.actor!.type === "agent" ? "agent" as const : "user" as const;
34	    const actorId = ctx.actor!.type === "agent"
35	      ? (ctx.actor!.agentId ?? "unknown-agent")
36	      : (ctx.actor!.userId ?? "board");
37	    const companyIds = await svc.listCompanyIds();
38	    await Promise.all(
39	      companyIds.map((companyId) =>
40	        logActivity(db, {
41	          companyId,
42	          actorType,
43	          actorId,
44	          agentId: ctx.actor!.type === "agent" ? (ctx.actor!.agentId ?? null) : null,
45	          runId: null,
46	          action: "instance.settings.general_updated",
47	          entityType: "instance_settings",
48	          entityId: updated.id,
49	          details: {
50	            general: updated.general,
51	            changedKeys: Object.keys(patch).sort(),
52	          },
53	        }),
54	      ),
55	    );
56	    return Response.json(updated.general);
57	  };
58	
59	  // server/src/routes/instance-settings.ts:65
60	  const getExperimentalSettings: Handler = async (ctx) => {
61	    assertBoardOrgAccess(ctx);
62	    return Response.json(await svc.getExperimental());
63	  };
64	
65	  // server/src/routes/instance-settings.ts:72
66	  const patchExperimentalSettings: Handler = async (ctx) => {
67	    assertInstanceAdmin(ctx);
68	    const body = await ctx.json();
69	    const patch = patchInstanceExperimentalSettingsSchema.parse(body);
70	    const updated = await svc.updateExperimental(patch);
71	
72	    const actorType = ctx.actor!.type === "agent" ? "agent" as const : "user" as const;
73	    const actorId = ctx.actor!.type === "agent"
74	      ? (ctx.actor!.agentId ?? "unknown-agent")
75	      : (ctx.actor!.userId ?? "board");
76	    const companyIds = await svc.listCompanyIds();
77	    await Promise.all(
78	      companyIds.map((companyId) =>
79	        logActivity(db, {
80	          companyId,
81	          actorType,
82	          actorId,
83	          agentId: ctx.actor!.type === "agent" ? (ctx.actor!.agentId ?? null) : null,
84	          runId: null,
85	          action: "instance.settings.experimental_updated",
86	          entityType: "instance_settings",
87	          entityId: updated.id,
88	          details: {
89	            experimental: updated.experimental,
90	            changedKeys: Object.keys(patch).sort(),
91	          },
92	        }),
93	      ),
94	    );
95	    return Response.json(updated.experimental);
96	  };
97	
98	  // server/src/routes/instance-settings.ts:103
99	  const previewIssueGraphLivenessAutoRecovery: Handler = async (ctx) => {
100	    assertInstanceAdmin(ctx);
101	    const body = await ctx.json();
102	    const parsed = issueGraphLivenessAutoRecoveryRequestSchema.parse(body);
103	    return Response.json(await heartbeat.buildIssueGraphLivenessAutoRecoveryPreview({
104	      lookbackHours: parsed.lookbackHours,
105	    }));
106	  };
107	
108	  // server/src/routes/instance-settings.ts:113
109	  const runIssueGraphLivenessAutoRecovery: Handler = async (ctx) => {
110	    assertInstanceAdmin(ctx);
111	    const body = await ctx.json();
112	    const parsed = issueGraphLivenessAutoRecoveryRequestSchema.parse(body);
113	
114	    const actorType = ctx.actor!.type === "agent" ? "agent" as const : "user" as const;
115	    const actorId = ctx.actor!.type === "agent"
116	      ? (ctx.actor!.agentId ?? "unknown-agent")
117	      : (ctx.actor!.userId ?? "board");
118	    const result = await heartbeat.reconcileIssueGraphLiveness({
119	      runId: null,
120	      force: true,
121	      lookbackHours: parsed.lookbackHours,
122	    });
123	    const companyIds = await svc.listCompanyIds();
124	    await Promise.all(
125	      companyIds.map((companyId) =>
126	        logActivity(db, {
127	          companyId,
128	          actorType,
129	          actorId,
130	          agentId: ctx.actor!.type === "agent" ? (ctx.actor!.agentId ?? null) : null,
131	          runId: null,
132	          action: "instance.settings.issue_graph_liveness_auto_recovery_run",
133	          entityType: "instance_settings",
134	          entityId: "default",
135	          details: {
136	            lookbackHours: result.lookbackHours,
137	            escalationsCreated: result.escalationsCreated,
138	            existingEscalations: result.existingEscalations,
139	            skippedOutsideLookback: result.skippedOutsideLookback,
140	            escalationIssueIds: result.escalationIssueIds,
141	          },
142	        }),
143	      ),
144	    );
145	    return Response.json(result);
146	  };
147	
148	  return {
149	    getGeneralSettings,
150	    patchGeneralSettings,
151	    getExperimentalSettings,
152	    patchExperimentalSettings,
153	    previewIssueGraphLivenessAutoRecovery,
154	    runIssueGraphLivenessAutoRecovery,
155	  };
156	}
157	
158	export function instanceSettingsRoutes(db: Db) {
159	  const router = Router();
160	  const {
161	    getGeneralSettings,
162	    patchGeneralSettings,
163	    getExperimentalSettings,
164	    patchExperimentalSettings,
165	    previewIssueGraphLivenessAutoRecovery,
166	    runIssueGraphLivenessAutoRecovery,
167	  } = buildHandlers(db);
168	
169	  const storageSentinel = new Proxy({} as StorageService, {
170	    get(_target, prop) {
171	      throw new Error(`instanceSettings handler unexpectedly accessed storage.${String(prop)}`);
172	    },
173	  });
174	  const deps = { db, storage: storageSentinel };
175	
176	  router.get("/instance/settings/general", expressHandler(getGeneralSettings, deps));
177	  router.patch("/instance/settings/general", expressHandler(patchGeneralSettings, deps));
178	  router.get("/instance/settings/experimental", expressHandler(getExperimentalSettings, deps));
179	  router.patch("/instance/settings/experimental", expressHandler(patchExperimentalSettings, deps));
180	  router.post(
181	    "/instance/settings/experimental/issue-graph-liveness-auto-recovery/preview",
182	    expressHandler(previewIssueGraphLivenessAutoRecovery, deps),
183	  );
184	  router.post(
185	    "/instance/settings/experimental/issue-graph-liveness-auto-recovery/run",
186	    expressHandler(runIssueGraphLivenessAutoRecovery, deps),
187	  );
188	
189	  return router;
190	}
